// Copies the ONNX Runtime Web files that @huggingface/transformers loads at
// run time (the wasm backend, which also carries the C++ WebGPU runtime)
// from node_modules into public/ort/, so local transcription and embeddings
// load them SAME-ORIGIN: the app's CSP allows no CDN, and the files then
// also work offline. public/ort/ is git-ignored and regenerated by
// predev/prebuild, so the ~40 MB never enters the repo.
import { copyFileSync, existsSync, mkdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const dist = join(here, "..", "node_modules", "onnxruntime-web", "dist");
const outDir = join(here, "..", "public", "ort");

// `.asyncify` is what transformers.js picks by default (WebGPU + wasm); the
// plain build is its choice for Safari < 26 without WebGPU.
const FILES = [
  "ort-wasm-simd-threaded.asyncify.mjs",
  "ort-wasm-simd-threaded.asyncify.wasm",
  "ort-wasm-simd-threaded.mjs",
  "ort-wasm-simd-threaded.wasm",
];

if (!existsSync(dist)) {
  console.warn("copy-ort: onnxruntime-web not installed — local transcription / embeddings will fail to load");
  process.exit(0);
}
mkdirSync(outDir, { recursive: true });
let total = 0;
for (const name of FILES) {
  const src = join(dist, name);
  if (!existsSync(src)) {
    console.warn(`copy-ort: ${name} missing in onnxruntime-web/dist`);
    continue;
  }
  const dest = join(outDir, name);
  if (!existsSync(dest) || statSync(dest).size !== statSync(src).size) copyFileSync(src, dest);
  total += statSync(src).size;
}
console.log(`copy-ort: ${FILES.length} files → public/ort/ (${(total / 1e6).toFixed(1)} MB)`);
